import React,{useState,useEffect} from 'react';import {BrowserRouter,Routes,Route,useLocation,useNavigate,Navigate} from 'react-router-dom';import {Toaster} from 'react-hot-toast';import {QueryClient,QueryClientProvider} from '@tanstack/react-query';import {AuthProvider,useAuth} from './contexts/AuthContext';import Layout from './components/Layout';import PinSetup from './components/PinSetup';import Subscribe from './pages/Subscribe';import Login from './pages/Login';import Signup from './pages/Signup';import ForgotPassword from './pages/ForgotPassword';import ResetPassword from './pages/ResetPassword';import Dashboard from './pages/Dashboard';import POS from './pages/POS';import Inventory from './pages/Inventory';import Sales from './pages/Sales';import Reports from './pages/Reports';import Employees from './pages/Employees';import Returns from './pages/Returns';import ReturnHistory from './pages/ReturnHistory';import Settings from './pages/Settings';import Discounts from './pages/Discounts';import Profile from './pages/Profile';import SuperAdmin from './pages/SuperAdmin';import {AlertTriangle} from 'lucide-react';
const queryClient=new QueryClient();
function PrivateRoute({children}){const {user,loading,staff,hasActiveSubscription}=useAuth();const navigate=useNavigate();const location=useLocation();useEffect(()=>{if(!loading){if(!user)navigate('/login',{replace:true});else if(staff&&!staff.is_active)navigate('/login',{replace:true});}},[user,loading,staff,navigate]);if(loading)return<div className="min-h-screen flex items-center justify-center">Loading...</div>;if(!user||(staff&&!staff.is_active))return null;if(!hasActiveSubscription&&location.pathname!=='/app/settings'&&staff?.role==='admin'){return(<div className="min-h-screen flex items-center justify-center bg-gray-50 p-4"><div className="bg-white rounded-xl shadow-lg p-8 max-w-md text-center"><AlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-4"/><h1 className="text-2xl font-bold mb-2">Trial Expired</h1><p className="text-gray-600 mb-6">Your 3-day free trial has ended. Please subscribe to continue.</p><button onClick={()=>navigate('/app/settings')} className="bg-green-600 text-white px-6 py-3 rounded-lg font-medium">Go to Settings to Subscribe</button></div></div>);}return children;}
function PublicRoute({children}){const {user,loading}=useAuth();const navigate=useNavigate();useEffect(()=>{if(!loading&&user)navigate('/app',{replace:true});},[user,loading,navigate]);if(loading)return<div className="min-h-screen flex items-center justify-center">Loading...</div>;return children;}
function AppContent(){const {user,staff,loading,needsPinSetup,reloadStaff,markPinPromptAsShown}=useAuth();const [showPin,setShowPin]=useState(false);useEffect(()=>{if(needsPinSetup&&user&&staff)setShowPin(true);else setShowPin(false);},[needsPinSetup,user,staff]);if(loading)return<div className="min-h-screen flex items-center justify-center">Loading...</div>;return(<>{showPin&&<PinSetup onSuccess={()=>{setShowPin(false);reloadStaff();}} onClose={()=>{setShowPin(false);markPinPromptAsShown();}}/>}<Routes><Route path="/" element={<PublicRoute><Subscribe/></PublicRoute>}/><Route path="/subscribe" element={<PublicRoute><Subscribe/></PublicRoute>}/><Route path="/login" element={<PublicRoute><Login/></PublicRoute>}/><Route path="/signup" element={<PublicRoute><Signup/></PublicRoute>}/><Route path="/forgot-password" element={<ForgotPassword/>}/><Route path="/reset-password" element={<ResetPassword/>}/><Route path="/super-admin" element={<SuperAdmin/>}/><Route path="/app" element={<PrivateRoute><Layout/></PrivateRoute>}><Route index element={<Dashboard/>}/><Route path="pos" element={<POS/>}/><Route path="inventory" element={<Inventory/>}/><Route path="sales" element={<Sales/>}/><Route path="reports" element={<Reports/>}/><Route path="employees" element={<Employees/>}/><Route path="returns" element={<Returns/>}/><Route path="return-history" element={<ReturnHistory/>}/><Route path="settings" element={<Settings/>}/><Route path="discounts" element={<Discounts/>}/><Route path="profile" element={<Profile/>}/></Route><Route path="*" element={<Navigate to="/" replace/>}/></Routes></>);}
export default function App(){return(<QueryClientProvider client={queryClient}><AuthProvider><BrowserRouter><Toaster position="top-right"/><AppContent/></BrowserRouter></AuthProvider></QueryClientProvider>);}
